(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.04-t*0.5)*8 + Math.cos((y+w1y)*0.035+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.04+t*0.45)*8 + Math.sin((x+w1x)*0.03-t*0.55)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.6],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.4],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.45],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.55],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+1)*40, 0.14, 1.3, 0.35],
    [400+Math.cos(t*0.55+2)*70, 220+Math.sin(t*0.75+4)*50, 0.11, 2.1, 0.65],
    [200+Math.sin(t*0.25+6)*110, 200+Math.cos(t*0.45+2)*70, 0.075, 2.4, 0.5],
    [300+Math.cos(t*0.7+3)*80, 100+Math.sin(t*0.5+5)*60, 0.13, 1.6, 0.4]
  ];
  let aS = 0, iS = 0, diff = 0, tw = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    diff += Math.sin(d*f*1.3 - t*sp*0.8 + 2.0) * w * 0.5;
    tw += w;
  }
  aS /= tw; iS /= tw; diff /= tw;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1) + Math.sin(sx*0.07+sy*0.05-t*0.6)*0.5 + Math.sin(sx*0.09-sy*0.08+t*1.5)*0.3)/2.8 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2) + Math.sin(dist*0.08-ang*2-t*2.0)*0.4)*0.35;
  const cellX = Math.round(sx/25)*25, cellY = Math.round(sy/25)*25;
  const cellD = Math.sqrt((sx-cellX)**2 + (sy-cellY)**2);
  const cell = Math.sin(cellD*0.3-t)*0.3 + Math.sin(cellD*0.5+t*0.7)*0.2;
  const reaction = Math.tanh((aS - iS*0.7 + bg*0.3 + spiral + diff*0.2)*2.2);
  const diffusion = Math.tanh((diff + cell*0.15 + spiral*0.3)*1.8);
  const blend = reaction*0.65 + diffusion*0.35, v = blend*0.5+0.5;
  const pal = [[6,12,52],[12,45,85],[18,90,115],[25,140,130],[60,170,120],[150,190,80],[210,185,60],[220,150,55],[210,110,60],[185,65,60],[140,40,65],[85,25,55],[40,15,48],[6,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const edge = Math.abs(reaction), glow = edge > 0.6 ? (edge-0.6)*2.5 : 0;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25 + glow*0.3;
  const shift = glow * 0.1;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum + glow*30 - shift*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum + glow*20)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum + glow*15 + shift*50)|0)
  ];
}
